options.customCss:
@import url('https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700&family=Inter:wght@400;500&family=JetBrains+Mono:wght@400;500&display=swap');
:root{
  --ink:#e8f1ff;--muted:#93a4c3;--glass:rgba(255,255,255,.06);--glass-2:rgba(255,255,255,.10);--edge:rgba(255,255,255,.14);
  --c1:#22d3ee;--c2:#818cf8;--c3:#f472b6;--bg:#060912;
  --chat--font-family:'Inter',system-ui,sans-serif;
  --chat--color-primary:#22d3ee;--chat--color-primary-shade-50:#0ea5c6;--chat--color-primary-shade-100:#0891b2;
  --chat--color-secondary:#818cf8;--chat--color-secondary-shade-50:#6d78f0;
  --chat--color-white:#ffffff;--chat--color-light:#0b1020;--chat--color-light-shade-50:#11182c;--chat--color-light-shade-100:#18213a;
  --chat--color-medium:#2a3553;--chat--color-dark:#e8f1ff;--chat--color-disabled:#5b6785;--chat--color-typing:#93a4c3;
  --chat--window--width:100%;--chat--window--height:100%;--chat--border-radius:18px;--chat--spacing:1rem;
  --chat--header--background:transparent;--chat--header--color:#e8f1ff;--chat--header--padding:1.6rem 1.6rem 1rem;
  --chat--heading--font-size:1.9rem;--chat--subtitle--font-size:.92rem;--chat--subtitle--line-height:1.5;
  --chat--body--background:transparent;--chat--footer--background:transparent;--chat--footer--color:#e8f1ff;
  --chat--message--font-size:.96rem;--chat--message--padding:.85rem 1.05rem;--chat--message--border-radius:18px;--chat--message-line-height:1.6;
  --chat--message--bot--background:rgba(255,255,255,.06);--chat--message--bot--color:#e8f1ff;--chat--message--bot--border:1px solid rgba(255,255,255,.12);
  --chat--message--user--background:linear-gradient(135deg,#0891b2,#6366f1);--chat--message--user--color:#ffffff;--chat--message--user--border:none;
  --chat--input--background:rgba(255,255,255,.06);--chat--input--text-color:#e8f1ff;--chat--input--border:1px solid rgba(255,255,255,.14);
  --chat--input--border-radius:16px;--chat--input--font-size:1rem;--chat--input--padding:1rem 1.1rem;
  --chat--input--send--button--background:transparent;--chat--input--send--button--color:#22d3ee;--chat--input--send--button--background-hover:transparent;
  --chat--button--background:#22d3ee;--chat--button--color:#060912;--chat--button--background--hover:#67e8f9;
}
html,body{background:var(--bg)!important;color:var(--ink);min-height:100%;overflow:hidden}
body::before{content:"";position:fixed;inset:-20%;z-index:0;pointer-events:none;filter:blur(70px);opacity:.55;
  background:radial-gradient(35% 40% at 20% 25%,rgba(34,211,238,.55),transparent 70%),radial-gradient(30% 35% at 80% 20%,rgba(129,140,248,.55),transparent 70%),radial-gradient(35% 40% at 60% 85%,rgba(244,114,182,.35),transparent 70%);
  animation:aurora 18s ease-in-out infinite alternate}
body::after{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;opacity:.18;
  background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:44px 44px;
  mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%);-webkit-mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%)}
@keyframes aurora{0%{transform:translate(0,0) rotate(0deg) scale(1)}50%{transform:translate(4%,-3%) rotate(8deg) scale(1.08)}100%{transform:translate(-4%,3%) rotate(-6deg) scale(1)}}
.n8n-chat,.chat-wrapper,.chat-layout{position:relative;z-index:1;background:transparent!important}
.chat-layout{max-width:900px;margin:0 auto;height:100vh;display:flex;flex-direction:column}
.chat-header{position:relative;padding-left:5.6rem!important;border-bottom:1px solid rgba(255,255,255,.08);backdrop-filter:blur(10px)}
.chat-header::before{content:"";position:absolute;left:1.6rem;top:1.55rem;width:3.1rem;height:3.1rem;border-radius:50%;
  background:conic-gradient(from 0deg,#22d3ee,#818cf8,#f472b6,#22d3ee);animation:spin 6s linear infinite,glow 2.8s ease-in-out infinite;
  -webkit-mask:radial-gradient(circle,transparent 38%,#000 40%);mask:radial-gradient(circle,transparent 38%,#000 40%)}
.chat-header::after{content:"";position:absolute;left:2.45rem;top:2.4rem;width:1.4rem;height:1.4rem;border-radius:50%;
  background:radial-gradient(circle at 35% 30%,#ffffff,#67e8f9 35%,#6366f1 80%);box-shadow:0 0 22px 6px rgba(34,211,238,.55);animation:breathe 2.8s ease-in-out infinite}
@keyframes spin{to{transform:rotate(360deg)}}@keyframes glow{50%{filter:drop-shadow(0 0 14px rgba(129,140,248,.9))}}@keyframes breathe{50%{transform:scale(1.18);box-shadow:0 0 34px 10px rgba(129,140,248,.6)}}
.chat-heading h1{font-family:'Sora',sans-serif;font-weight:700;letter-spacing:-.02em;margin:0;
  background:linear-gradient(90deg,#e8f1ff,#67e8f9,#a5b4fc,#f9a8d4,#e8f1ff);background-size:250% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:shimmer 7s linear infinite}
@keyframes shimmer{to{background-position:250% 0}}
.chat-header p{color:var(--muted)!important;margin-top:.35rem}
.chat-body{background:transparent!important}
.chat-messages-list{padding:1.4rem 1.6rem!important}
.chat-message{animation:msgIn .55s cubic-bezier(.2,.8,.2,1) both;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 8px 30px rgba(0,0,0,.25)}
.chat-message-from-bot{border-top-left-radius:6px!important}
.chat-message-from-user{border-top-right-radius:6px!important;box-shadow:0 10px 30px rgba(99,102,241,.35)}
@keyframes msgIn{from{opacity:0;transform:translateY(14px) scale(.98);filter:blur(4px)}to{opacity:1;transform:none;filter:none}}
.chat-message-markdown a{color:#67e8f9;text-decoration:none;border-bottom:1px dashed rgba(103,232,249,.5)}
.chat-message-from-user a{color:#fff}
.chat-message table{border-collapse:collapse;font-size:.86rem;margin:.5em 0;width:100%}
.chat-message th{color:#a5b4fc;font-weight:600;text-align:left;border-bottom:1px solid rgba(255,255,255,.18);padding:6px 8px}
.chat-message td{border-bottom:1px solid rgba(255,255,255,.08);padding:6px 8px;vertical-align:top}
.chat-message code{background:rgba(255,255,255,.08);border-radius:6px;padding:1px 5px}
.chat-footer{border-top:1px solid rgba(255,255,255,.08);padding:1rem 1.4rem 1.3rem!important;backdrop-filter:blur(10px)}
.chat-inputs{position:relative;border-radius:18px;padding:2px;background:linear-gradient(120deg,rgba(34,211,238,.6),rgba(129,140,248,.6),rgba(244,114,182,.6),rgba(34,211,238,.6));background-size:300% 100%;animation:border 8s linear infinite}
@keyframes border{to{background-position:300% 0}}
.chat-inputs textarea{background:#0b1020!important;border:none!important;border-radius:16px!important;color:#e8f1ff!important}
.chat-inputs textarea::placeholder{color:#7d8bab}
.chat-inputs:focus-within{box-shadow:0 0 0 4px rgba(34,211,238,.15),0 0 40px rgba(129,140,248,.35)}
.chat-input-send-button{transition:transform .2s}
.chat-input-send-button:not(:disabled){animation:pulse 2.2s ease-in-out infinite}
.chat-input-send-button:hover{transform:scale(1.12)}
@keyframes pulse{50%{filter:drop-shadow(0 0 10px rgba(34,211,238,.9))}}
::-webkit-scrollbar{width:8px}::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:8px}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important}}

.chat-footer .chat-input{border-radius:18px;padding:2px!important;background:linear-gradient(120deg,rgba(34,211,238,.7),rgba(129,140,248,.7),rgba(244,114,182,.7),rgba(34,211,238,.7))!important;background-size:300% 100%!important;animation:border 8s linear infinite}
.chat-footer .chat-inputs{background:#0b1020!important;border-radius:16px!important;padding:0!important;animation:none!important;overflow:hidden}
.chat-footer .chat-input:focus-within{box-shadow:0 0 0 4px rgba(34,211,238,.15),0 0 40px rgba(129,140,248,.35)}
.chat-inputs-controls{background:transparent!important;display:flex;align-items:center;padding:0 .7rem}
.chat-message table{display:block;overflow-x:auto;max-width:100%}
.chat-message td,.chat-message th{word-break:normal;overflow-wrap:normal;min-width:3.5em}
.chat-message td a{word-break:break-all;display:inline-block;min-width:12em}

/* --- Aurora upgrade --- */
.chat-layout::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;
  background-image:radial-gradient(1.5px 1.5px at 12% 18%,#fff,transparent),radial-gradient(1px 1px at 28% 72%,#c7d2fe,transparent),radial-gradient(1.5px 1.5px at 46% 34%,#a5f3fc,transparent),radial-gradient(1px 1px at 63% 12%,#fff,transparent),radial-gradient(1.5px 1.5px at 78% 58%,#f9a8d4,transparent),radial-gradient(1px 1px at 88% 26%,#fff,transparent),radial-gradient(1px 1px at 36% 90%,#a5f3fc,transparent),radial-gradient(1.5px 1.5px at 92% 84%,#c7d2fe,transparent),radial-gradient(1px 1px at 6% 62%,#fff,transparent),radial-gradient(1px 1px at 54% 66%,#f9a8d4,transparent);
  animation:twinkle 5s ease-in-out infinite alternate}
@keyframes twinkle{from{opacity:.3}to{opacity:.9}}
.chat-message-from-bot{background:linear-gradient(rgba(13,18,36,.72),rgba(13,18,36,.72)) padding-box,linear-gradient(135deg,rgba(34,211,238,.6),rgba(129,140,248,.25),rgba(244,114,182,.5)) border-box!important;border:1px solid transparent!important;box-shadow:0 8px 30px rgba(0,0,0,.25),0 0 24px rgba(34,211,238,.08)!important}
.chat-message-from-bot:hover{box-shadow:0 8px 30px rgba(0,0,0,.25),0 0 30px rgba(129,140,248,.25)!important}
.chat-header p::before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:#34d399;box-shadow:0 0 10px #34d399;margin-right:8px;vertical-align:1px;animation:live 2s ease-in-out infinite}
@keyframes live{50%{opacity:.35}}
.chat-message code,.chat-message pre{font-family:'JetBrains Mono',monospace!important;font-size:.86em}
.chat-message strong{background:linear-gradient(90deg,#a5f3fc,#c4b5fd);-webkit-background-clip:text;background-clip:text;color:transparent}
.chat-message-from-user strong{color:#fff;background:none;-webkit-background-clip:initial;background-clip:initial}
/* user bubble fix: gradients need background, not background-color */
.chat-message-from-user{background:linear-gradient(135deg,#0891b2,#6366f1 60%,#a855f7)!important;color:#fff!important}
